-- stg_mp_transfers_report: part 1 of 2, 12000 rows. NOT APPLIED, branch only.
-- Licence on every row comes from the FILE, never the filename.
create table if not exists public.stg_mp_transfers_report (
  manifest text,
  inv_nbr text,
  origin_lic text,
  origin_facility text,
  origin_facility_type text,
  dest_lic text,
  destination_facility text,
  dest_facility_type text,
  type text,
  created text,
  created_by_user text,
  received text,
  received_by_user text,
  voided text,
  package text,
  state text,
  item text,
  item_category text,
  shipper_dollar_amount text,
  receiver_dollar_amount text,
  actual_ship_d text,
  uom text,
  actual_rcv_d text,
  uom_2 text,
  count_ship_d text,
  uom_3 text,
  count_rcv_d text,
  uom_4 text,
  unit_weight_g text,
  count_weight_g text,
  weight_ship_d text,
  uom_5 text,
  weight_rcv_d text,
  uom_6 text,
  gross_wgt text,
  uom_7 text,
  count_var text,
  weight_var text,
  source_file text not null,
  file_sha256 text not null,
  licence text not null,
  file_window text,
  ingested_at timestamptz not null default now()
);
alter table public.stg_mp_transfers_report enable row level security;
drop policy if exists stg_mp_transfers_report_read on public.stg_mp_transfers_report;
create policy stg_mp_transfers_report_read on public.stg_mp_transfers_report for select to authenticated using (true);
